'use strict';
EZ.spriteVersion = 'motion-4';
// Imagem fornecida pelo usuário, incorporada sem dependência de URL externa.
EZ.survivorData = 'data:image/png;base64,';
// PNG 1536 x 1024 incorporado acima; assets/survivor-motion.png é a referência.
// Recortes sem rótulos. As legendas de algumas direções da imagem são inconsistentes.
EZ.spriteFrames = {
  idle: [
    [37, 39, 53, 113], [130, 40, 52, 115], [215, 40, 42, 113], [301, 40, 47, 113],
    [383, 40, 50, 111], [473, 40, 44, 113], [552, 40, 50, 113], [638, 40, 49, 115]
  ]
};
// Ordem de tela: S, SO, O, NO, N, NE, L, SE. Pares espelhados mantêm a orientação.
// O pivô acompanha a pelve, não o centro da mochila/retângulo.
EZ.survivorDirections = [
  {frame: 0, pivot: 26, flip: false}, {frame: 1, pivot: 28, flip: false},
  {frame: 2, pivot: 25, flip: true}, {frame: 6, pivot: 29, flip: true},
  {frame: 4, pivot: 25, flip: false}, {frame: 6, pivot: 29, flip: false},
  {frame: 2, pivot: 25, flip: false}, {frame: 3, pivot: 25, flip: false}
];
EZ.survivorArmRegions = {
  0: [[0, 33, 11, 42], [42, 33, 11, 42]],
  1: [[0, 34, 12, 40], [40, 33, 12, 42]],
  2: [[29, 31, 13, 43]],
  3: [[0, 33, 12, 39], [37, 33, 10, 39]],
  4: [[0, 31, 11, 39], [39, 31, 11, 39]],
  6: [[36, 32, 14, 43]]
};
EZ.loadSprites = function() {
  if (EZ.survivorImage && !EZ.spriteError) return Promise.resolve(true);
  EZ.survivorImage = null;
  EZ.spriteError = '';
  return new Promise(resolve => {
    const img = new Image();
    img.decoding = 'async';
    const fail = message => {
      EZ.survivorImage = null;
      EZ.spriteError = message;
      console.error('[ECOZUMBI sprites]', message);
      resolve(false);
    };
    img.onload = () => {
      if ((img.naturalWidth || img.width) !== 1536 || (img.naturalHeight || img.height) !== 1024) {
        fail('A prancha do sobrevivente tem dimensões incorretas. Use o sprites.js completo.');
        return;
      }
      EZ.survivorImage = img;
      resolve(true);
    };
    img.onerror = () => fail('Não foi possível decodificar a imagem do sobrevivente. Recarregue os arquivos atualizados.');
    img.src = EZ.survivorData;
  });
};
EZ.drawSurvivorRig = function(motion) {
  const c = EZ.ctx, spec = EZ.survivorDirections[motion.direction];
  const f = EZ.spriteFrames.idle[spec.frame], scale = .4;
  const height = Math.round(f[3] * scale), hip = Math.round(height * .59);
  const sourceHip = hip / height * f[3], ground = 1;
  const top = ground - height, pivot = spec.pivot * scale;
  c.save();
  if (spec.flip) c.scale(-1, 1);
  const flip = spec.flip ? -1 : 1;
  const localForward = motion.fx * flip;
  const arms = EZ.survivorArmRegions[spec.frame] || [];
  // Mantém os braços em uma camada própria; a mochila permanece presa ao tronco.
  function bodyBand(sx, sw, sy, sh, dx, dy, dw, dh) {
    let spans = [[sx, sx + sw]];
    for (const [ax, ay, aw, ah] of arms) {
      if (sy + sh * .5 < ay || sy + sh * .5 >= ay + ah) continue;
      const next = [];
      for (const [lo, hi] of spans) {
        if (ax >= hi || ax + aw <= lo) next.push([lo, hi]);
        else {
          if (ax > lo) next.push([lo, ax]);
          if (ax + aw < hi) next.push([ax + aw, hi]);
        }
      }
      spans = next;
    }
    for (const [lo, hi] of spans) {
      const x0 = Math.round(dx + (lo - sx) / sw * dw);
      const x1 = Math.round(dx + (hi - sx) / sw * dw);
      if (x1 > x0) c.drawImage(EZ.survivorImage, f[0] + lo, f[1] + sy, hi - lo, sh, x0, dy, x1 - x0, dh);
    }
  }
  // Cada perna usa a textura original. O deslocamento é contínuo do quadril ao pé,
  // com flexão no joelho. Faixas contíguas evitam rasgos entre partes do corpo.
  const parts = [[0, spec.pivot, 0], [spec.pivot, f[2] - spec.pivot, Math.PI]];
  for (const [sx, sw, offset] of parts) {
    const step = Math.sin(motion.phase + offset);
    const lift = Math.max(0, Math.cos(motion.phase + offset));
    const footX = step * motion.stride * (localForward * .85 + (sx === 0 ? -.18 : .18));
    const footY = -lift * motion.lift + step * motion.fy * motion.gait * .65;
    const kneeX = footX * .45 + lift * localForward * motion.run * motion.gait * 1.2;
    function warp(u) {
      const x = u < .5 ? kneeX * (u * 2) : kneeX + (footX - kneeX) * ((u - .5) * 2);
      const y = motion.bob * (1 - u) + footY * u - Math.sin(u * Math.PI) * lift * motion.run * motion.gait;
      return {x, y};
    }
    for (let row = hip; row < height; row++) {
      const u0 = (row - hip) / (height - hip), u1 = (row + 1 - hip) / (height - hip);
      const a = warp(u0), b = warp(u1);
      const y0 = Math.round(top + row + a.y), y1 = Math.round(top + row + 1 + b.y);
      if (y1 <= y0) continue;
      const sy = sourceHip + (f[3] - sourceHip) * u0;
      bodyBand(sx, sw, sy, (f[3] - sourceHip) * (u1 - u0),
        Math.round(sx * scale - pivot + a.x), y0, Math.round(sw * scale), y1 - y0);
    }
  }
  // Tronco por cima da ligação do quadril; respiração, balanço e inclinação da corrida.
  for (let row = hip; row >= 0; row--) {
    const u = row / hip, stretch = motion.breath * (1 - u);
    const y = Math.round(top + row + motion.bob - stretch);
    const y2 = Math.round(top + row + 1 + motion.bob - motion.breath * (1 - (row + 1) / hip));
    const dx = (motion.lean * flip + motion.sway) * (1 - u);
    bodyBand(0, f[2], row / height * f[3], f[3] / height,
      Math.round(-pivot + dx), y, Math.round(f[2] * scale), Math.max(1, y2 - y));
  }
  for (let index = 0; index < arms.length; index++) {
    const [ax, ay, aw, ah] = arms[index];
    const step = -Math.sin(motion.phase + (index ? Math.PI : 0));
    const armSwing = step * motion.gait * (1.3 + motion.run * .9);
    const rows = Math.round(ah * scale);
    for (let row = 0; row < rows; row++) {
      const u = row / rows, srcY = ay + ah * u;
      const upper = 1 - Math.min(1, srcY / sourceHip);
      const x = ax * scale - pivot + (motion.lean * flip + motion.sway) * upper + armSwing * u * localForward;
      const y = top + srcY * height / f[3] + motion.bob - motion.breath * upper - Math.abs(armSwing) * u * .4;
      c.drawImage(EZ.survivorImage, f[0] + ax, f[1] + srcY, aw, ah / rows,
        Math.round(x), Math.round(y), Math.round(aw * scale), 1);
    }
  }
  c.restore();
};
EZ.drawSurvivor = function(a) {
  if (!EZ.survivorImage) return false;
  const c = EZ.ctx, p = EZ.project(a), motion = EZ.survivorMotion(a);
  c.save();
  c.imageSmoothingEnabled = false;
  if (a.swimming) {
    const surface = EZ.project({x: a.x, y: a.y, z: 0});
    c.beginPath();
    c.rect(p.x - 40, p.y - 60, 80, Math.max(0, surface.y - (p.y - 60)));
    c.clip();
  }
  c.translate(p.x, p.y);
  EZ.drawSurvivorRig(motion);
  c.restore();
  if (a.swimming) {
    const q = EZ.project({x: a.x, y: a.y, z: 0});
    const wave = Math.floor((a.animation?.time || 0) * 5) % 3;
    EZ.line({x: q.x - 10 - wave, y: q.y}, {x: q.x + 10 + wave, y: q.y}, '#87b3ba', 1);
    EZ.line({x: q.x - 7, y: q.y + 3}, {x: q.x + 7, y: q.y + 3}, '#527d8a', 1);
    return true;
  }
  const s = EZ.state, m = s.input.mouse;
  const hand = {x: p.x + motion.fx * 4, y: p.y - 24 + motion.bob};
  if (a.weapon && s.tool === 'shoot') {
    let angle = Math.atan2(m.y - hand.y, m.x - hand.x);
    if (a.reload > 0) angle += Math.sin(a.reload * 7) * .25;
    const length = a.weapon === 'pistol' ? 7 : 13;
    const recoil = (a.animation?.recoil || 0) * 2;
    const tip = {x: hand.x + Math.cos(angle) * (length - recoil), y: hand.y + Math.sin(angle) * (length - recoil)};
    EZ.line(hand, tip, '#283336', 3);
    if (a.cooldown > EZ.weapons[a.weapon].rate - .06) EZ.rect(tip.x - 1, tip.y - 1, 3, 3, '#f4cf82');
  } else if (s.tool === 'chop' || s.tool === 'mine') {
    const progress = a.attackTime > 0 ? 1 - a.attackTime / .35 : 0;
    const swing = a.attackTime > 0 ? Math.sin(progress * Math.PI) : 0;
    const angle = a.attackTime > 0 ? Math.atan2(m.y - hand.y, m.x - hand.x) - 1.2 + swing * 2.2 : 1.1;
    hand.x += motion.fx * swing * 2;
    const tip = {x: hand.x + Math.cos(angle) * 10, y: hand.y + Math.sin(angle) * 10};
    EZ.line(hand, tip, '#443a30', 2);
    const blade = {x: hand.x + Math.cos(angle) * 4, y: hand.y + Math.sin(angle) * 4};
    EZ.line(blade, tip, '#b6b8a0', 1);
    if (s.tool === 'mine') EZ.line({x: tip.x - 3, y: tip.y - 1}, {x: tip.x + 3, y: tip.y + 1}, '#a6a998', 2);
  }
  return true;
};
